float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float wear = U.p0.x;
    float t = iTime;
    // A tracking band rolls up the frame and shoves its rows sideways.
    float band = 1.0 - smoothstep(0.0, 0.035, abs(uv.y - fract(t * 0.13)));
    float row = hash(vec2(floor(uv.y * 240.0), floor(t * 30.0))) - 0.5;
    float shove = band * row * 0.08 * wear + sin(uv.y * 40.0 + t * 3.0) * 0.0015 * wear;
    vec2 p = vec2(uv.x + shove, uv.y);
    float bleed = 0.006 * wear;
    vec3 col = vec3(texture(iChannel0, p + vec2(bleed, 0.0)).r,
                    texture(iChannel0, p).g,
                    texture(iChannel0, p - vec2(bleed, 0.0)).b);
    // Tape has little horizontal resolution: smear along the line.
    vec3 smear = 0.5 * (texture(iChannel0, p + vec2(0.003, 0.0)).rgb + texture(iChannel0, p - vec2(0.003, 0.0)).rgb);
    col = mix(col, smear, 0.4);
    float l = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(vec3(l), col, 0.75);
    col *= 0.9 + 0.1 * sin(fragCoord.y * 3.14159);
    col += (hash(fragCoord + t) - 0.5) * 0.12 * wear;
    col += band * 0.15 * wear;
    vec2 v = uv - 0.5;
    col *= 1.0 - dot(v, v) * 0.9;
    fragColor = vec4(col, 1.0);
}
